import flask
from flask import request, jsonify, g
import sqlite3
import os
import hashlib
import time

app = flask.Flask(__name__)
DB_PATH = os.environ.get('DB_PATH', '/data/users.db')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DB_PATH)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DB_PATH)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        password_hash TEXT NOT NULL,
        email TEXT,
        role TEXT DEFAULT 'user',
        api_key TEXT,
        last_login TIMESTAMP
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        username TEXT,
        details TEXT,
        ts TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

@app.route('/api/v1/users/search', methods=['GET'])
def search_users():
    """Search users by various fields. Supports partial matching."""
    field = request.args.get('field', 'username')
    value = request.args.get('q', '')
    limit = request.args.get('limit', '20')

    # Validate field against allowed columns
    allowed_fields = ['username', 'email', 'role', 'api_key']
    if field not in allowed_fields:
        return jsonify({'error': 'Invalid field'}), 400

    # Build query - field is validated above so safe to interpolate
    # But value is user-controlled and directly interpolated
    query = f"SELECT id, username, email, role, last_login FROM users WHERE {field} LIKE '%{value}%' LIMIT {limit}"

    try:
        db = get_db()
        results = db.execute(query).fetchall()
        users = [dict(row) for row in results]

        # Log the search
        db.execute(
            "INSERT INTO audit_log (action, username, details) VALUES (?, ?, ?)",
            ('search', request.remote_addr, f'field={field}, q={value}')
        )
        db.commit()
        return jsonify({'results': users, 'count': len(users)})
    except sqlite3.Error as e:
        return jsonify({'error': 'Database error', 'detail': str(e)}), 500

@app.route('/api/v1/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    db = get_db()
    user = db.execute(
        'SELECT id, username, email, role, last_login FROM users WHERE id = ?',
        (user_id,)
    ).fetchone()
    if user is None:
        return jsonify({'error': 'Not found'}), 404
    return jsonify(dict(user))

@app.route('/api/v1/users', methods=['POST'])
def create_user():
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({'error': 'Missing fields'}), 400

    password_hash = hashlib.sha256(data['password'].encode()).hexdigest()
    api_key = hashlib.sha256(f"{data['username']}{time.time()}".encode()).hexdigest()

    try:
        db = get_db()
        db.execute(
            'INSERT INTO users (username, password_hash, email, role, api_key) VALUES (?, ?, ?, ?, ?)',
            (data['username'], password_hash, data.get('email', ''), 'user', api_key)
        )
        db.commit()
        return jsonify({'status': 'created', 'api_key': api_key}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username exists'}), 409

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.3.1'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
